-- Draft migration for Prompt 04: external IdentityService user mapping.
-- This script is intentionally additive. It does not remove or rewrite Users,
-- Roles, password, role_id, or any existing FK that points to Users.id.

CREATE TABLE IF NOT EXISTS "IdentityUserLinks" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "legacy_user_id" bigint NOT NULL,
    "identity_user_id" uuid NOT NULL,
    "created_at" timestamp with time zone NOT NULL DEFAULT now(),
    "is_active" boolean NOT NULL DEFAULT true,
    CONSTRAINT "FK_IdentityUserLinks_Users_legacy_user_id"
        FOREIGN KEY ("legacy_user_id")
        REFERENCES "Users" ("id")
        ON DELETE RESTRICT
);

CREATE UNIQUE INDEX IF NOT EXISTS "IX_IdentityUserLinks_legacy_user_id"
    ON "IdentityUserLinks" ("legacy_user_id");

CREATE UNIQUE INDEX IF NOT EXISTS "IX_IdentityUserLinks_identity_user_id"
    ON "IdentityUserLinks" ("identity_user_id");

CREATE INDEX IF NOT EXISTS "IX_IdentityUserLinks_is_active"
    ON "IdentityUserLinks" ("is_active");

