-- Validation checks:

-- Users without active IdentityService mapping.
SELECT u."id", u."login"
FROM "Users" u
LEFT JOIN "IdentityUserLinks" l
    ON l."legacy_user_id" = u."id"
    AND l."is_active" = true
WHERE l."id" IS NULL;

-- Duplicate external identities, should return zero rows.
SELECT "identity_user_id", count(*)
FROM "IdentityUserLinks"
WHERE "is_active" = true
GROUP BY "identity_user_id"
HAVING count(*) > 1;

-- Duplicate legacy users, should return zero rows.
SELECT "legacy_user_id", count(*)
FROM "IdentityUserLinks"
WHERE "is_active" = true
GROUP BY "legacy_user_id"
HAVING count(*) > 1;

-- Existing user relations remain attached to Users.id.
SELECT
    u."id" AS "legacy_user_id",
    count(DISTINCT owned_courses."id") AS "owned_courses",
    count(DISTINCT course_binds."id") AS "course_binds",
    count(DISTINCT practical_binds."id") AS "practical_binds",
    count(DISTINCT case_files."id") AS "case_files",
    count(DISTINCT test_results."id") AS "test_results"
FROM "Users" u
LEFT JOIN "Courses" owned_courses ON owned_courses."user_id" = u."id"
LEFT JOIN "CourseBindUsers" course_binds ON course_binds."user_id" = u."id"
LEFT JOIN "PracticalBindUsers" practical_binds ON practical_binds."user_id" = u."id"
LEFT JOIN "CaseFiles" case_files ON case_files."user_id" = u."id"
LEFT JOIN "TestResults" test_results ON test_results."user_id" = u."id"
GROUP BY u."id"
ORDER BY u."id";
